function notify(t,error=false){const n=$("iaNotice");if(n){n.hidden=false;n.textContent=t;n.style.background=error?"#fff0ef":"#eaf8f2";n.style.color=error?"#a12b2b":"#16634a";}}
function tableName(k){return config[k].table}
async function fetchRows(k){const c=config[k],r=await api.db.from(c.table).select(c.select).eq("institution_id",api.institutionId).order("created_at",{ascending:false}).limit(500);if(r.error)throw r.error;cache[k]=r.data||[];if(k==="attendance"&&cache[k].length){const ids=[...new Set(cache[k].map(x=>x.student_id).filter(Boolean))];if(ids.length){const sr=await api.db.from("students").select("id,full_name,admission_number").eq("institution_id",api.institutionId).in("id",ids);if(!sr.error){const map=new Map((sr.data||[]).map(x=>[x.id,(x.full_name||"Student")+" · "+(x.admission_number||"")]));cache[k].forEach(x=>x.student_label=map.get(x.student_id)||x.student_id);}}}return cache[k];}
function addActionHeaders(){Object.values(config).forEach(c=>{const body=$(c.body),thead=body?.closest("table")?.querySelector("thead tr");if(thead&&!thead.querySelector(".ia-actions-head")){const th=document.createElement("th");th.className="ia-actions-head";th.textContent="Actions";thead.append(th);}});}
function draw(k){const c=config[k],body=$(c.body);if(!body)return;const q=($("iaModuleSearch_"+k)?.value||document.querySelector("#view-"+(k==="programs"||k==="courses"?"academic":k)+" input[type=search]")?.value||"").toLowerCase();const data=(cache[k]||[]).filter(x=>c.search.some(f=>String(x[f]??"").toLowerCase().includes(q)));body.replaceChildren();if(!data.length){const tr=document.createElement("tr"),td=document.createElement("td");td.colSpan=c.cols.length+1;td.className="ia-empty";td.textContent="No matching records found.";tr.append(td);body.append(tr);}data.forEach(x=>{const tr=document.createElement("tr");tr.dataset.recordId=x.id;tr.dataset.moduleKey=k;c.cols.forEach(([key])=>{const td=document.createElement("td"),v=key==="student_id"?(x.student_label||x.student_id):x[key];td.textContent=key==="approved"?(v?"Yes":"No"):key==="is_published"?(v?"Yes":"No"):v??"—";if(key==="status"||key==="approval_status"){td.innerHTML="";const b=document.createElement("span");b.className="ia-status";b.textContent=String(v??"pending").replace(/_/g," ");td.append(b);}tr.append(td);});const td=document.createElement("td");td.className="ia-row-actions";td.innerHTML=(k==="admissions"&&x.status!=="enrolled"?'<button type="button" data-convert="admissions" data-id="'+esc(x.id)+'" class="ia-primary-btn">Register student</button> ':"")+'<button type="button" data-edit="'+esc(k)+'" data-id="'+esc(x.id)+'" class="ia-text-btn">Edit</button> <button type="button" data-delete="'+esc(k)+'" data-id="'+esc(x.id)+'" class="ia-danger-btn">Delete</button>';tr.append(td);body.append(tr);});const countId={students:"iaStudentCount",staff:"iaStaffCount"}[k];if(countId)$(countId).textContent=data.length+" records";const summary=$("iaSummary_"+k);if(summary){const statuses={};data.forEach(row=>{const st=String(row.status||row.approval_status||"recorded").replace(/_/g," ");statuses[st]=(statuses[st]||0)+1;});summary.textContent=data.length+" total · "+Object.entries(statuses).slice(0,3).map(([st,n])=>n+" "+st).join(" · ");}}
function fieldHtml(f){const [key,label,type="text",required=false,opts=[]]=f;let el;if(type==="select")el='<select name="'+key+'" '+(required?"required":"")+'>'+opts.map(o=>'<option value="'+esc(o)+'">'+esc(o)+'</option>').join("")+'</select>';else if(type==="textarea")el='<textarea name="'+key+'" rows="3"></textarea>';else el='<input name="'+key+'" type="'+type+'" '+(required?"required":"")+'>';return '<label class="ia-form-field"><span>'+esc(label)+(required?' *':'')+'</span>'+el+'</label>';}
async function openForm(k,row){const c=config[k];let dlg=$("iaModuleDialog");if(!dlg){dlg=document.createElement("dialog");dlg.id="iaModuleDialog";dlg.className="ia-module-dialog";document.body.append(dlg);}dlg.innerHTML='<form method="dialog" class="ia-module-form" id="iaModuleForm"><div class="ia-module-form-head"><div><small>CAMPUS NEXUS · INSTITUTION RECORD</small><h2>'+(row?"Update ":"Create ")+({students:"student",staff:"staff member",programs:"programme",courses:"unit / course",exams:"examination",attendance:"attendance record",resources:"learning resource",admissions:"admission applicant",hr:"HR record",timetable:"timetable session",placements:"clinical placement",research:"research project",welfare:"welfare case"}[k]||"record")+'</h2></div><button type="button" data-close-dialog aria-label="Close">×</button></div><div class="ia-module-form-grid">'+c.create.map(f=>fieldHtml(f)).join("")+'</div><div class="ia-module-form-actions"><button type="button" class="ia-secondary-btn" data-close-dialog>Cancel</button><button type="submit" class="ia-primary-btn">Save record</button></div></form>';const form=$("iaModuleForm");if(k==="attendance"||k==="placements"){const studentSelect=form.elements.namedItem("student_id");if(studentSelect){studentSelect.innerHTML='<option value="">Select student</option>';const sr=await api.db.from("students").select("id,full_name,admission_number").eq("institution_id",api.institutionId).order("full_name").limit(1000);if(sr.error){notify(sr.error.message,true);return;}(sr.data||[]).forEach(st=>{const o=document.createElement("option");o.value=st.id;o.textContent=(st.full_name||"Student")+" · "+(st.admission_number||st.id.slice(0,8));o.dataset.name=st.full_name||"";o.dataset.admission=st.admission_number||"";studentSelect.append(o);});if(k==="placements")studentSelect.addEventListener("change",()=>{const opt=studentSelect.selectedOptions[0];const nm=form.elements.namedItem("student_name"),ad=form.elements.namedItem("admission_number");if(nm&&opt?.dataset.name)nm.value=opt.dataset.name;if(ad&&opt?.dataset.admission)ad.value=opt.dataset.admission;});}}if(row)Object.entries(row).forEach(([key,val])=>{const el=form.elements.namedItem(key);if(el&&val!=null)el.value=val;});form.addEventListener("submit",async e=>{e.preventDefault();const btn=form.querySelector('[type="submit"]');btn.disabled=true;btn.textContent="Saving…";const payload={institution_id:api.institutionId};c.create.forEach(([key,,type])=>{const el=form.elements.namedItem(key);if(type==="file")return;if(el&&el.value!=="")payload[key]=type==="number"?Number(el.value):el.value;});if(k==="exams"){payload.exam_name=payload.title;payload.approval_status="draft";payload.is_published=false;}if(k==="staff")payload.approved=false;if(k==="attendance"){payload.marked_by=api.profile.full_name||api.user.email;payload.timestamp=payload.date?new Date(payload.date+"T12:00:00").toISOString():new Date().toISOString();}if(k==="resources"){payload.approval_status="pending";payload.uploaded_by=api.user.id;payload.uploaded_by_name=api.profile.full_name||api.user.email;const file=form.elements.namedItem("resource_file")?.files?.[0];if(file){if(file.size>50*1024*1024){notify("Resource file exceeds the 50 MB upload limit.",true);btn.disabled=false;btn.textContent="Save record";return;}const safe=file.name.normalize("NFKD").replace(/[^a-zA-Z0-9._-]+/g,"_");const path=api.institutionId+"/"+Date.now()+"_"+safe;const up=await api.db.storage.from("resources").upload(path,file,{upsert:false,contentType:file.type||"application/octet-stream"});if(up.error){notify("File upload failed: "+up.error.message,true);btn.disabled=false;btn.textContent="Save record";return;}payload.file_path=path;payload.file_name=file.name;payload.file_size=file.size;payload.file_type=file.type;payload.file_url=api.db.storage.from("resources").getPublicUrl(path).data.publicUrl;}}const save= row?api.db.from(c.table).update(payload).eq("id",row.id).eq("institution_id",api.institutionId):api.db.from(c.table).insert(payload);const result=await save;if(result.error){notify(result.error.message,true);btn.disabled=false;btn.textContent="Save record";return;}dlg.close();notify("Record saved successfully.");await fetchRows(k);draw(k);if(api.refresh)api.refresh().catch(()=>{});});dlg.querySelectorAll("[data-close-dialog]").forEach(b=>b.addEventListener("click",()=>dlg.close()));dlg.showModal();}
async function remove(k,id){if(!confirm("Delete this record? This action cannot be undone."))return;const c=config[k],r=await api.db.from(c.table).delete().eq("id",id).eq("institution_id",api.institutionId);if(r.error){notify(r.error.message,true);return;}notify("Record deleted.");await fetchRows(k);draw(k);if(api.refresh)api.refresh().catch(()=>{});}
async function convertAdmission(id){const applicant=(cache.admissions||[]).find(x=>String(x.id)===String(id));if(!applicant)return;const admissionNumber=prompt("Enter the official admission number for "+applicant.applicant_name+":");if(!admissionNumber||!admissionNumber.trim())return;const payload={institution_id:api.institutionId,full_name:applicant.applicant_name,email:applicant.email||null,phone:applicant.phone||null,course:applicant.programme||null,admission_number:admissionNumber.trim(),status:"active",block:"pending",intake_year:applicant.intake||null};const created=await api.db.from("students").insert(payload);if(created.error){notify("Student registration failed: "+created.error.message,true);return;}const updated=await api.db.from("institution_admissions").update({status:"enrolled"}).eq("id",id).eq("institution_id",api.institutionId);if(updated.error){notify("Student was created, but application status could not be updated: "+updated.error.message,true);return;}notify("Applicant registered as a student successfully.");await fetchRows("admissions");draw("admissions");if(api.refresh)await api.refresh();}
function exportRows(k){const c=config[k],q=($("iaModuleSearch_"+k)?.value||"").toLowerCase(),data=(cache[k]||[]).filter(x=>c.search.some(f=>String(x[f]??"").toLowerCase().includes(q)));if(!data.length){notify("There are no records to export.",true);return;}const cols=[...new Set(c.cols.map(x=>x[0]).concat(["created_at"]))];const csv=[cols.join(","),...data.map(row=>cols.map(key=>'"'+String(row[key]??"").replace(/"/g,'""')+'"').join(","))].join("\\r\\n");const blob=new Blob(["\\ufeff",csv],{type:"text/csv;charset=utf-8"});const url=URL.createObjectURL(blob);const a=document.createElement("a");a.href=url;a.download="campus-nexus-"+k+"-"+new Date().toISOString().slice(0,10)+".csv";document.body.append(a);a.click();a.remove();URL.revokeObjectURL(url);}
function addToolbar(k,container){if(!container||container.querySelector('[data-create="'+k+'"]'))return;const view=k==="programs"||k==="courses"?"academic":k;const hasSearch=!!document.getElementById("iaModuleSearch_"+k)||(["students","staff"].includes(k)&&!!document.querySelector("#view-"+view+" input[type=search]"));if(!hasSearch){const search=document.createElement("input");search.type="search";search.id="iaModuleSearch_"+k;search.placeholder="Search "+(k==="students"?"students":k==="staff"?"staff":k==="programs"?"programmes":k==="courses"?"units":k==="exams"?"examinations":k==="attendance"?"attendance":k==="resources"?"resources":k==="admissions"?"applicants":k==="hr"?"staff":k==="timetable"?"sessions":k==="placements"?"placements":k==="research"?"research projects":"welfare cases")+"…";search.className="ia-module-search";search.addEventListener("input",()=>draw(k));container.append(search);}const b=document.createElement("button");b.type="button";b.className="ia-primary-btn";b.dataset.create=k;b.innerHTML='<i class="fa-solid fa-plus"></i> Add '+(k==="students"?"student":k==="staff"?"staff member":k==="programs"?"programme":k==="courses"?"unit / course":k==="exams"?"examination":k==="admissions"?"applicant":k==="hr"?"staff member":k==="timetable"?"session":k==="placements"?"placement":k==="research"?"research project":"welfare case");container.append(b);const summary=document.createElement("span");summary.id="iaSummary_"+k;summary.className="ia-module-summary";summary.textContent="Loading records…";container.append(summary);const exp=document.createElement("button");exp.type="button";exp.className="ia-secondary-btn ia-export-btn";exp.dataset.export=k;exp.textContent="Export CSV";container.append(exp);}
async function load(k){if(!config[k])return;try{await fetchRows(k);draw(k);}catch(e){notify("Unable to load "+k+": "+e.message,true);}}


